-- Sample database: HR Management
-- GENERATED by app/sample_dbs/generate.py — do not edit by hand

CREATE TABLE departments (
  id        integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name      varchar(60) NOT NULL UNIQUE,
  location  varchar(60),
  budget    numeric(14,2)
);
CREATE TABLE positions (
  id          integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  title       varchar(80) NOT NULL UNIQUE,
  min_salary  numeric(10,2) NOT NULL,
  max_salary  numeric(10,2) NOT NULL,
  CHECK (max_salary >= min_salary)
);
CREATE TABLE employees (
  id             integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  first_name     varchar(50) NOT NULL,
  last_name      varchar(50) NOT NULL,
  email          varchar(120) NOT NULL UNIQUE,
  gender         char(1) CHECK (gender IN ('M','F')),
  hire_date      date NOT NULL,
  department_id  integer REFERENCES departments(id),
  position_id    integer NOT NULL REFERENCES positions(id),
  manager_id     integer REFERENCES employees(id),
  commission_pct numeric(4,2),
  is_active      boolean NOT NULL DEFAULT true
);
CREATE TABLE salaries (
  id              integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  employee_id     integer NOT NULL REFERENCES employees(id),
  amount          numeric(10,2) NOT NULL CHECK (amount > 0),
  effective_from  date NOT NULL,
  effective_to    date,
  CHECK (effective_to IS NULL OR effective_to > effective_from)
);
CREATE INDEX idx_employees_dept ON employees(department_id);
CREATE INDEX idx_employees_manager ON employees(manager_id);
CREATE INDEX idx_salaries_emp ON salaries(employee_id);

COMMENT ON TABLE departments IS 'แผนก — แผนก Research ยังไม่มีพนักงาน';
COMMENT ON TABLE positions IS 'ตำแหน่งงานและช่วงเงินเดือน';
COMMENT ON TABLE employees IS 'พนักงาน — manager_id อ้างถึง employees.id (Self Join / Recursive CTE)';
COMMENT ON COLUMN employees.manager_id IS 'หัวหน้าโดยตรง (NULL = CEO)';
COMMENT ON COLUMN employees.department_id IS 'แผนก (NULL = ยังไม่ได้สังกัดแผนก)';
COMMENT ON COLUMN employees.commission_pct IS 'ค่าคอมมิชชัน (เฉพาะฝ่ายขาย, อื่น ๆ เป็น NULL)';
COMMENT ON TABLE salaries IS 'ประวัติเงินเดือน — effective_to IS NULL คือเงินเดือนปัจจุบัน';





